mapper.select:
SELECT p.id, p.member_id, p.category_id, pc.name AS category_name, p.title, p.content, p.status, p.blocked_reason, p.view_count, p.like_count, p.created_at, p.updated_at
FROM posts p JOIN post_categories pc ON pc.id = p.category_id
WHERE p.id = #{postId}

SELECT COUNT(*)
FROM post_views pv
WHERE pv.post_id = #{postId}

SELECT EXISTS (
SELECT 1
FROM post_categories pc
WHERE pc.id = #{categoryId}
AND pc.is_active = 1
)

mapper.update:
UPDATE posts
SET category_id = #{categoryId},
title = #{title},
content = #{content}
WHERE id = #{id}
AND member_id = #{memberId}
AND status = 'PUBLISHED'

UPDATE posts
SET status = 'DELETED'
WHERE id = #{postId}
AND member_id = #{memberId}
AND status = 'PUBLISHED'

mapper.select:
SELECT c.id, c.post_id, c.member_id, CASE WHEN c.status = 'PUBLISHED' THEN c.content END AS content, c.status, c.created_at
FROM comments c
WHERE c.post_id = #{postId}
ORDER BY c.created_at DESC, c.id DESC LIMIT #{limit}

SELECT c.id, c.post_id, c.member_id, CASE WHEN c.status = 'PUBLISHED' THEN c.content END AS content, c.status, c.created_at
FROM comments c
WHERE c.id = #{commentId}

mapper.update:
UPDATE comments
SET status = 'DELETED'
WHERE id = #{commentId}
AND post_id = #{postId}
AND member_id = #{memberId}
AND status = 'PUBLISHED'

mapper.delete:
DELETE FROM post_likes
WHERE post_id = #{postId}
AND member_id = #{memberId}

mapper.select:
SELECT EXISTS (
SELECT 1
FROM post_likes pl
WHERE pl.post_id = #{postId}
AND pl.member_id = #{memberId}
)

SELECT COUNT(*)
FROM post_likes pl
WHERE pl.post_id = #{postId}

SELECT EXISTS (
SELECT 1
FROM post_reports pr
WHERE pr.post_id = #{postId}
AND pr.reporter_id = #{reporterId}
)

SELECT EXISTS (
SELECT 1
FROM popular_post_batch_runs r
WHERE r.ranking_date = #{rankingDate}
)
